package main
import ("fmt";"net/http";"os")
func main(){
p:=os.Getenv("PORT")
if p==""{p="10000"}
http.HandleFunc("/",func(w http.ResponseWriter,r *http.Request){fmt.Fprint(w,html)})
http.ListenAndServe(":"+p,nil)
}
const html = `<!doctype html><meta charset=utf-8><meta name=viewport content='width=device-width'><center><b>WASHUSEMA</b></center><div><select id=m><option>1<option>2<option>3<option>4<option>5<option>6<option>7<option>8<option>9<option>10<option>11<option>12</select><input id=y value=2026><button onclick=R()>Sawa</button></div><div style=display:flex><div style=flex:1;background:#2e7d32;color:#fff>MAPATO<br><span id=a>0</span></div><div style=flex:1;background:#c00;color:#fff>MATUMIZI<br><span id=b>0</span></div><div style=flex:1;background:#1565c0;color:#fff>BAKAA<br><span id=c>0</span></div></div><div><button onclick=W()>+Wanachama</button><div id=wl></div></div><div><select id=sw></select><select id=sa><option>Hisa<option>Ada<option>RibaAda<option>Mkopo<option>Rejesho<option>RibaRejesho<option>Tunisha<option>Ufadhili</select><input id=kv><button onclick=M()>Hifadhi</button></div><div><button onclick=E()>Excel</button><div id=hi></div></div></div><script>D=JSON.parse(localStorage.v||'null')||{w:[],m:[]};function S(){localStorage.v=JSON.stringify(D);R()}function W(){j=prompt('Jina:');if(j){j=j.trim();if(j){D.w.push({j:j});S()}}}function M(){w=(sw.value||'').trim();a=sa.value.toLowerCase();k=+kv.value;if(!w||!k)return alert('Jaza');if(a=='ribaada')a='faini_ada';if(a=='ribarejesho')a='faini_rejesho';D.m.push({w:w,a:a,k:k,mm:+m.value,yy:+y.value});if(a=='mkopo'){f=k*0.05|0;D.m.push({w:w,a:'fomu',k:f,mm:+m.value,yy:+y.value})}kv.value='';S()}function R(){let mp=0,mt=0;D.m.forEach(t=>{if(['hisa','ada','faini_ada','fomu','marejesho','faini_rejesho','tunisha','ufadhili'].includes(t.a))mp+=t.k;if(t.a=='mkopo')mt+=t.k});a.innerText=mp;b.innerText=mt;c.innerText=mp-mt;wl.innerHTML=sw.innerHTML='';if(!D.w.length)wl.innerHTML='Hakuna wanachama';D.w.forEach((x,i)=>{wl.innerHTML+=x.j+' <button onclick=EW('+i+')>E</button> <button onclick=SW('+i+')>X</button><br>';sw.innerHTML+='<option>'+x.j+'</option>'});hi.innerHTML='';D.m.slice().reverse().forEach((t,idx)=>{let i=D.m.length-1-idx;hi.innerHTML+=t.w+'-'+t.a+'-'+t.k+' <button onclick=Ed('+i+')>E</button> <button onclick=SM('+i+')>X</button><br>'})}function SW(i){D.w.splice(i,1);S()}function EW(i){j=prompt('Jina jipya:',D.w[i].j);if(j){j=j.trim();if(j){D.w[i].j=j;S()}}}function SM(i){if(confirm('Futa?')){D.m.splice(i,1);S()}}function Ed(i){v=prompt('Kiasi kipya:',D.m[i].k);if(v&&+v>0){D.m[i].k=+v;S()}}function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;')}function Rr(r){s='<Row>';r.forEach(v=>{s+='<Cell><Data>'+esc(v)+'</Data></Cell>'});return s+'</Row>'}function E(){x=D.m;if(!x.length)return alert('Hakuna');r1=[['Jina','Ada','RibaAda']];r2=[['Jina','Mkopo','Rejesho','Baki']];r3=[['Jina','Hisa']];mp={};am={};ar={};dm={};hm={};rm={};sh=0;x.forEach(t=>{let w=(t.w||'').trim();let k=w.toLowerCase();if(mp[k]==null){mp[k]=w;am[k]=0;ar[k]=0;hm[k]=0;rm[k]=0;dm[k]=0}if(t.a=='ada')am[k]+=t.k;if(t.a=='faini_ada'){ar[k]+=t.k;sh+=t.k}if(t.a=='mkopo')dm[k]+=t.k;if(t.a=='fomu')sh+=t.k;if(t.a=='hisa')hm[k]+=t.k;if(t.a=='marejesho')rm[k]+=t.k;if(t.a=='faini_rejesho')sh+=t.k;if(t.a=='tunisha')sh+=t.k;if(t.a=='ufadhili')sh+=t.k});n=D.w.length||1;sp=sh/n|0;for(k in am){r1.push([mp[k],am[k],ar[k]])}for(k in dm){r2.push([mp[k],dm[k],rm[k],dm[k]-rm[k]])}for(j in D.w){let jn=D.w[j].j;let k=jn.toLowerCase();let d=(hm[k]||0)+(am[k]||0);r3.push([jn,d+sp])}function Sh(n,r){h='<Worksheet ss:Name="'+n+'"><Table>';r.forEach(t=>{h+=Rr(t)});return h+'</Table></Worksheet>'}xml='<Workbook xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">'+Sh('Ada',r1)+Sh('Mkopo',r2)+Sh('Hisa',r3)+'</Workbook>';b=new Blob([xml]);u=URL.createObjectURL(b);z=document.createElement('a');z.href=u;z.download='Washusema.xls';document.body.appendChild(z);z.click()}R();</script>`
